type FastInput struct {
	is       *bufio.Reader
	buf      []byte
	bufLen   int
	bufOff   int
	next     int
}

func newFastInput() *FastInput {
	return &FastInput{
		is:  bufio.NewReader(os.Stdin),
		buf: make([]byte, 1<<13),
	}
}

func (f *FastInput) read() int {
	for f.bufLen == f.bufOff {
		f.bufOff = 0
		n, err := f.is.Read(f.buf)
		if err != nil {
			f.bufLen = -1
			return -1
		}
		f.bufLen = n
	}
	b := f.buf[f.bufOff]
	f.bufOff++
	return int(b)
}

func (f *FastInput) skipBlank() {
	for f.next >= 0 && f.next <= 32 {
		f.next = f.read()
	}
}

func (f *FastInput) readInt() int {
	sign := 1
	f.skipBlank()
	if f.next == '+' || f.next == '-' {
		sign = 1
		if f.next == '-' {
			sign = -1
		}
		f.next = f.read()
	}
	val := 0
	if sign == 1 {
		for f.next >= '0' && f.next <= '9' {
			val = val*10 + f.next - '0'
			f.next = f.read()
		}
	} else {
		for f.next >= '0' && f.next <= '9' {
			val = val*10 - f.next + '0'
			f.next = f.read()
		}
	}
	return val
}

type FastOutput struct {
	writer *bufio.Writer
}

func newFastOutput() *FastOutput {
	return &FastOutput{
		writer: bufio.NewWriter(os.Stdout),
	}
}

func (f *FastOutput) println(c int) {
	f.writer.WriteString(itoa(c))
	f.writer.WriteByte('\n')
}

func (f *FastOutput) close() {
	f.writer.Flush()
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := false
	if n < 0 {
		neg = true
		n = -n
	}
	var buf [20]byte
	pos := len(buf)
	for n > 0 {
		pos--
		buf[pos] = byte(n%10) + '0'
		n /= 10
	}
	if neg {
		pos--
		buf[pos] = '-'
	}
	return string(buf[pos:])
}
